import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Phone } from 'lucide-react';
import { useState } from 'react';
import { Button } from '@/components/ui/button';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '/', label: 'Home' },
    { href: '/services', label: 'Services' },
    { href: '/about', label: 'About' },
    { href: '/contact', label: 'Contact' },
  ];

  return (
    <header className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b border-border shadow-sm">
      <div className="container mx-auto px-4">
        <div className="flex h-20 md:h-24 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Shine Bright Cleaning logo"
              className="h-10 md:h-12 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navItems.map((item) => (
              <Link
                key={item.href}
                to={item.href}
                className={`text-sm font-medium transition-colors duration-200 hover:text-primary ${
                  location.pathname === item.href
                    ? 'text-primary font-semibold'
                    : 'text-foreground/70'
                }`}
              >
                {item.label}
              </Link>
            ))}
          </nav>

          {/* CTA + Phone */}
          <div className="hidden md:flex items-center gap-4">
            <a
              href="tel:+15551234567"
              className="flex items-center gap-1.5 text-sm font-medium text-foreground/70 hover:text-primary transition-colors duration-200"
            >
              <Phone size={15} />
              (555) 123-4567
            </a>
            <Button
              asChild
              className="bg-yellow-400 hover:bg-yellow-300 text-gray-900 font-semibold rounded-full px-5 transition-colors duration-200 shadow-sm"
            >
              <Link to="/contact">Get a Free Quote</Link>
            </Button>
          </div>

          {/* Mobile menu toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 hover:bg-muted rounded-md transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-4">
            <nav className="flex flex-col gap-1">
              {navItems.map((item) => (
                <Link
                  key={item.href}
                  to={item.href}
                  className={`text-sm font-medium transition-colors hover:text-primary py-2.5 px-2 rounded-md ${
                    location.pathname === item.href
                      ? 'text-primary bg-primary/5 font-semibold'
                      : 'text-foreground/70'
                  }`}
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  {item.label}
                </Link>
              ))}
              <div className="pt-3 flex flex-col gap-2">
                <a
                  href="tel:+15551234567"
                  className="flex items-center gap-2 text-sm font-medium text-foreground/70 py-2 px-2"
                >
                  <Phone size={15} />
                  (555) 123-4567
                </a>
                <Button
                  asChild
                  className="bg-yellow-400 hover:bg-yellow-300 text-gray-900 font-semibold rounded-full transition-colors duration-200"
                >
                  <Link to="/contact" onClick={() => setIsMobileMenuOpen(false)}>
                    Get a Free Quote
                  </Link>
                </Button>
              </div>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

